const DeliveriesAdmin=(()=>{const $=id=>document.getElementById(id);async function load(){$("dlv-status").textContent="Loading…";const res=await Api.post("adminListDeliveries",{token:Auth.getToken(),status:$("dlv-filter").value});if(!res.ok||!res.counts){$("dlv-status").textContent=res&&res.error||"Could not load deliveries.";return}$("dlv-status").textContent="";$("dlv-mode").textContent=res.enabled?res.allIslands?"Mwakete drivers are ON on every island. A job is only for a store and buyer on the same island, and only drivers there see it.":`Mwakete drivers are ON for: ${res.areas.join(", ")} (within one island only).`:"Mwakete drivers are OFF (Script Property DELIVERY_JOBS). Nothing here is visible to sellers or drivers yet.";const c=res.counts;const card=(label,v,sub)=>`<div class="kpi-card"><span class="kpi-label">${escapeHtml(label)}</span><strong class="kpi-value">${v}</strong>${sub?`<span class="kpi-sub${/stuck|fail/i.test(sub)&&v?" is-warning":""}">${escapeHtml(sub)}</span>`:""}</div>`;$("dlv-counts").innerHTML=card("Waiting for a driver",c.open,"")+card("On the way",c.active,"")+card("Failed / stuck",c.failed+c.stuck,`${c.failed} failed · ${c.stuck} stuck`)+card("Drivers online",c.driversOnline,`${c.driversPending} waiting for approval`)+card("Payments to check",c.paymentsToCheck,`${c.refundsDue} refund${c.refundsDue===1?"":"s"} due`);$("dlv-bank").textContent=res.bankDetailsSet?"":"Mwakete’s bank details are not set (Script Property MWAKETE_BANK_DETAILS), so sellers cannot pay for wallet deliveries yet.";$("dlv-drivers").innerHTML=res.drivers.length?`<table class="dash-table"><thead><tr><th scope="col">Driver</th><th scope="col">Vehicle / area</th><th scope="col">Record</th><th scope="col">Status</th></tr></thead><tbody>${res.drivers.map(d=>`<tr>\n      <td data-label="Driver">${escapeHtml(d.name)}<span class="dash-table-sub"><a href="tel:${escapeHtml(d.phone)}">${escapeHtml(d.phone)}</a> · ${escapeHtml(d.email)}</span></td>\n      <td data-label="Vehicle / area">${escapeHtml(d.vehicle)}<span class="dash-table-sub">${escapeHtml(d.area)}</span></td>\n      <td data-label="Record">${d.delivered} delivered · ${d.failed} failed</td>\n      <td data-label="Status"><strong>${escapeHtml(d.status)}</strong>${d.online?" · online":""}${d.note?`<span class="dash-table-sub">${escapeHtml(d.note)}</span>`:""}\n        <span class="dlv-actions">${d.status!=="approved"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="approved">Approve</button>`:""}\n        ${d.status==="pending"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="rejected">Reject</button>`:""}\n        ${d.status==="approved"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="suspended">Suspend</button>`:""}</span></td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No driver applications yet.</p>';$("dlv-jobs").innerHTML=res.jobs.length?`<table class="dash-table"><thead><tr><th scope="col">Order</th><th scope="col">Driver</th><th scope="col">Fee</th><th scope="col">Status</th></tr></thead><tbody>${res.jobs.map(j=>`<tr>\n      <td data-label="Order"><a href="../order-room.html?order=${encodeURIComponent(j.orderId)}&amp;as=admin">${escapeHtml(j.orderId)}</a><span class="dash-table-sub">${escapeHtml(j.storeName)} → ${escapeHtml(j.dropoff)}</span></td>\n      <td data-label="Driver">${j.driverName?`${escapeHtml(j.driverName)}<span class="dash-table-sub"><a href="tel:${escapeHtml(j.driverPhone)}">${escapeHtml(j.driverPhone)}</a></span>`:"—"}\n        ${j.location?`<span class="dash-table-sub"><a href="${escapeHtml(j.location.link)}" target="_blank" rel="noopener">Live location</a></span>`:""}</td>\n      <td data-label="Fee">${formatMoney(j.fee)}<span class="dash-table-sub">${j.payStatus?escapeHtml(j.payLabel):j.feePaid?"Paid":"Not marked paid"}</span>\n        ${j.payStatus==="submitted"||j.payStatus==="rejected"?`<span class="dash-table-sub">Reference <strong>${escapeHtml(j.payRef)}</strong> · bank ref ${escapeHtml(j.payBankRef)} · ${j.payAmount==null?"":formatMoney(j.payAmount)}</span>`:""}\n        ${j.payNote?`<span class="dash-table-sub">${escapeHtml(j.payNote)}</span>`:""}\n        ${j.payStatus==="submitted"?`<span class="dlv-actions"><button type="button" class="btn btn-small" data-pay="confirm" data-job="${escapeHtml(j.jobId)}" data-fee="${escapeHtml(j.fee)}">Confirm received</button>\n          <button type="button" class="btn btn-small" data-pay="reject" data-job="${escapeHtml(j.jobId)}">Not received</button></span>`:""}\n        ${j.payStatus==="refund_due"?`<span class="dlv-actions"><button type="button" class="btn btn-small" data-pay="refund" data-job="${escapeHtml(j.jobId)}">I sent the refund</button></span>`:""}</td>\n      <td data-label="Status">${escapeHtml(j.statusLabel)}${j.stuck?' <span class="status-badge status-problem">Stuck</span>':""}${j.failReason?`<span class="dash-table-sub">${escapeHtml(j.failReason)}</span>`:""}</td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No delivery jobs here.</p>'}async function onPay(b){const jobId=b.dataset.job,kind=b.dataset.pay;let action,payload;if(kind==="confirm"){if(!confirm("Only confirm after you have checked the REAL bank statement (not a screenshot) and the money is in Mwakete’s account. Continue?"))return;const got=prompt("Amount that arrived ($):",b.dataset.fee);if(got===null||got==="")return;action="adminConfirmJobPayment";payload={amountReceived:got,checkedStatement:true}}else if(kind==="reject"){const reason=prompt("What is wrong? (the seller will see it)");if(!reason)return;action="adminRejectJobPayment";payload={reason:reason}}else{const bankRef=prompt("Bank reference of the refund you sent:");if(!bankRef)return;action="adminMarkJobRefunded";payload={bankRef:bankRef}}b.disabled=true;const res=await Api.post(action,Object.assign({token:Auth.getToken(),jobId:jobId},payload));if(!res.ok){alert(res.error||"Not saved.");b.disabled=false;return}await load()}async function onClick(e){const pay=e.target.closest("[data-pay]");if(pay){await onPay(pay);return}const b=e.target.closest("[data-driver]");if(!b)return;const status=b.dataset.set;let reason="";if(status!=="approved"){reason=prompt(`Reason to ${status==="rejected"?"reject":"suspend"} this driver (they will see it):`)||"";if(!reason)return}else if(!confirm("Approve this driver? Only approve someone you have spoken to."))return;b.disabled=true;const res=await Api.post("adminSetDriverStatus",{token:Auth.getToken(),driverId:b.dataset.driver,status:status,reason:reason});if(!res.ok){alert(res.error||"Not saved.");b.disabled=false;return}await load()}function init(){if(!$("deliveries"))return;$("dlv-filter").addEventListener("change",load);$("dlv-drivers").addEventListener("click",onClick);$("dlv-jobs").addEventListener("click",onClick);load()}return{init:init}})();